import java.util.*;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.*;

public class Main {
    public static void main(String[] args) throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();
        String json = "[{\"id\":1,\"judul\":\"Belajar\"},{\"id\":2,\"judul\":\"Beli kopi\"}]";
        List<?> polos = mapper.readValue(json, List.class);
        System.out.println(polos.get(0).getClass().getSimpleName());
        List<Todo> todos = mapper.readValue(json, new TypeReference<List<Todo>>() {});
        System.out.println(todos.get(1).getJudul());
    }
}

class Todo {
    private int id;
    private String judul;
    private boolean selesai;

    public Todo() {
    }

    public Todo(int id, String judul) {
        this.id = id;
        this.judul = judul;
    }

    public int getId() {
        return id;
    }

    public void setId(int id) {
        this.id = id;
    }

    public String getJudul() {
        return judul;
    }

    public void setJudul(String judul) {
        this.judul = judul;
    }

    public boolean isSelesai() {
        return selesai;
    }

    public void setSelesai(boolean selesai) {
        this.selesai = selesai;
    }
