import com.fasterxml.jackson.databind.*;

public class Main {
    public static void main(String[] args) throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();
        List<Todo> daftar = new ArrayList<>();
        daftar.add(new Todo(1, "Belajar JSON"));
        daftar.add(new Todo(2, "Beli kopi"));
        String json = mapper.writeValueAsString(daftar);
        System.out.println(json);

        List<Todo> dibaca = mapper.readValue(json, new TypeReference<List<Todo>>() {});
        for (Todo t : dibaca) {
            System.out.println(t.getId() + ". " + t.getJudul());
