        System.out.println(atur.get("tema") + " " + atur.get("ukuranHuruf") + " " + atur.get("bahasa"));

        String hariIni = "[{\"id\":1,\"judul\":\"A\",\"selesai\":true},{\"id\":2,\"judul\":\"B\"},{\"id\":3,\"judul\":\"C\",\"selesai\":true}]";
